CREATE OR REPLACE FUNCTION public.campaign_member_matches_filter(p_member_id uuid,p_filter jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_matches_segment(m.id,COALESCE(p_filter->>'member_status',CASE WHEN p_filter->>'status' IN ('active','expired','all') THEN p_filter->>'status' END,'all')) AND (NULLIF(trim(p_filter->>'goal'),'') IS NULL OR position(lower(trim(p_filter->>'goal')) in lower(COALESCE(m.fitness_goals,'')))>0) AND (NULLIF(p_filter->>'last_attendance_before','') IS NULL OR (SELECT max(check_in) FROM public.member_attendance WHERE member_id=m.id)<(p_filter->>'last_attendance_before')::timestamptz) AND (NULLIF(p_filter->>'last_attendance_after','') IS NULL OR (SELECT max(check_in) FROM public.member_attendance WHERE member_id=m.id)>(p_filter->>'last_attendance_after')::timestamptz) FROM public.members m WHERE m.id=p_member_id $$;
REVOKE ALL ON FUNCTION public.campaign_member_matches_filter(uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.campaign_member_matches_filter(uuid,jsonb) TO service_role;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.resolve_campaign_audience_v2(uuid,jsonb,integer)'::regprocedure); IF position('public.member_matches_segment(m.id, v_status)' in d)=0 THEN RAISE EXCEPTION 'Resolver changed'; END IF; EXECUTE replace(d,'public.member_matches_segment(m.id, v_status)','public.campaign_member_matches_filter(m.id, p_filter)'); END $$;
CREATE OR REPLACE FUNCTION public.inapp_campaign_user_ids(p_branch_id uuid,p_filter jsonb) RETURNS TABLE(user_id uuid) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF public.rpc_guard_applies('inapp_campaign_user_ids') AND NOT (public.has_any_role(auth.uid(),ARRAY['owner','admin']::public.app_role[]) OR (public.has_role(auth.uid(),'manager') AND public.is_branch_staff(p_branch_id,false))) THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501'; END IF;
 IF p_branch_id IS NULL OR p_filter IS NULL OR jsonb_typeof(p_filter)<>'object' OR COALESCE(p_filter->>'audience_kind','members') NOT IN ('members','members_and_staff','staff') THEN RAISE EXCEPTION 'Unsupported audience' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT DISTINCT COALESCE(m.user_id,p.id) FROM public.resolve_campaign_audience_v2(p_branch_id,p_filter,24) r LEFT JOIN public.members m ON r.source_type='member' AND m.id=r.source_ref_id AND m.branch_id=p_branch_id LEFT JOIN public.profiles p ON r.source_type='staff' AND p.id=r.source_ref_id WHERE COALESCE(m.user_id,p.id) IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.inapp_campaign_user_ids(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.inapp_campaign_user_ids(uuid,jsonb) TO authenticated,service_role;
ALTER TABLE public.announcements ADD COLUMN targeted_delivery boolean NOT NULL DEFAULT false;
CREATE TABLE public.inapp_delivery_jobs(announcement_id uuid PRIMARY KEY REFERENCES public.announcements(id) ON DELETE CASCADE,branch_id uuid NOT NULL REFERENCES public.branches(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','retry','done','failed','cancelled')),next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,claim_token uuid,materialized_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),last_error text);
GRANT SELECT ON public.inapp_delivery_jobs TO authenticated; GRANT ALL ON public.inapp_delivery_jobs TO service_role; ALTER TABLE public.inapp_delivery_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Managers read scoped In-App jobs" ON public.inapp_delivery_jobs FOR SELECT TO authenticated USING ((SELECT public.has_any_role(auth.uid(),ARRAY['owner','admin']::public.app_role[])) OR branch_id IN (SELECT public.managed_branch_ids(auth.uid())));
CREATE TABLE public.inapp_delivery_recipients(announcement_id uuid NOT NULL REFERENCES public.announcements(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','suppressed','failed')),attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(announcement_id,user_id));
GRANT SELECT ON public.inapp_delivery_recipients TO authenticated; GRANT ALL ON public.inapp_delivery_recipients TO service_role; ALTER TABLE public.inapp_delivery_recipients ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Recipients read own assignment" ON public.inapp_delivery_recipients FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE INDEX idx_inapp_jobs_due ON public.inapp_delivery_jobs(next_attempt_at) WHERE status IN ('pending','retry'); CREATE INDEX idx_inapp_jobs_stalled ON public.inapp_delivery_jobs(lease_until) WHERE status='running'; CREATE INDEX idx_inapp_recipients_user ON public.inapp_delivery_recipients(user_id,announcement_id); CREATE INDEX idx_inapp_recipients_pending ON public.inapp_delivery_recipients(announcement_id) WHERE status='pending';
ALTER POLICY "View active announcements in scope" ON public.announcements USING(is_active=true AND (publish_at IS NULL OR publish_at<=now()) AND (expire_at IS NULL OR expire_at>now()) AND (branch_id IS NULL OR branch_id IN (SELECT public.user_visible_branch_ids(auth.uid()))) AND (NOT targeted_delivery OR id IN (SELECT announcement_id FROM public.inapp_delivery_recipients WHERE user_id=(SELECT auth.uid()))));
CREATE OR REPLACE FUNCTION public.create_inapp_announcement(p_branch_id uuid,p_filter jsonb,p_title text,p_message text,p_publish_at timestamptz DEFAULT NULL,p_attachment jsonb DEFAULT NULL,p_request_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid:=COALESCE(p_request_id,gen_random_uuid()); v_time timestamptz:=COALESCE(p_publish_at,now()); BEGIN
 IF public.rpc_guard_applies('create_inapp_announcement') AND NOT (public.has_any_role(auth.uid(),ARRAY['owner','admin']::public.app_role[]) OR (public.has_role(auth.uid(),'manager') AND public.is_branch_staff(p_branch_id,false))) THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501'; END IF;
 IF p_branch_id IS NULL OR p_title IS NULL OR p_message IS NULL OR length(trim(p_title)) NOT BETWEEN 1 AND 255 OR length(trim(p_message)) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'Invalid announcement' USING ERRCODE='22023'; END IF;
 IF p_attachment IS NOT NULL AND (COALESCE(p_attachment->>'kind','') NOT IN ('image','document','video') OR COALESCE(p_attachment->>'url','') NOT LIKE 'https://%') THEN RAISE EXCEPTION 'Invalid attachment' USING ERRCODE='22023'; END IF;
 PERFORM * FROM public.inapp_campaign_user_ids(p_branch_id,p_filter);
 IF EXISTS(SELECT 1 FROM public.announcements WHERE id=v_id) THEN IF NOT EXISTS(SELECT 1 FROM public.announcements WHERE id=v_id AND branch_id=p_branch_id AND created_by=auth.uid() AND targeted_delivery AND audience_filter=p_filter AND title=trim(p_title) AND content=trim(p_message)) THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='23505'; END IF; RETURN v_id; END IF;
 INSERT INTO public.announcements(id,branch_id,title,content,target_audience,publish_at,created_by,audience_filter,targeted_delivery,attachment_url,attachment_kind,attachment_filename) VALUES(v_id,p_branch_id,trim(p_title),trim(p_message),COALESCE(p_filter->>'audience_kind','members'),v_time,auth.uid(),p_filter,true,p_attachment->>'url',p_attachment->>'kind',p_attachment->>'filename'); INSERT INTO public.inapp_delivery_jobs(announcement_id,branch_id,next_attempt_at) VALUES(v_id,p_branch_id,v_time); RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.create_inapp_announcement(uuid,jsonb,text,text,timestamptz,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_inapp_announcement(uuid,jsonb,text,text,timestamptz,jsonb,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.inapp_delivery_work_pending() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.inapp_delivery_jobs WHERE (status IN ('pending','retry') AND next_attempt_at<=now()) OR (status='running' AND lease_until<now())) $$;
REVOKE ALL ON FUNCTION public.inapp_delivery_work_pending() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.inapp_delivery_work_pending() TO service_role;
CREATE OR REPLACE FUNCTION public.claim_inapp_delivery(p_announcement_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.inapp_delivery_jobs; a public.announcements; token uuid:=gen_random_uuid(); users jsonb; BEGIN
 SELECT * INTO j FROM public.inapp_delivery_jobs WHERE (p_announcement_id IS NULL OR announcement_id=p_announcement_id) AND ((status IN ('pending','retry') AND next_attempt_at<=now()) OR (status='running' AND lease_until<now())) ORDER BY next_attempt_at LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO a FROM public.announcements WHERE id=j.announcement_id;
 IF a.is_active IS NOT TRUE OR (a.expire_at IS NOT NULL AND a.expire_at<=now()) THEN UPDATE public.inapp_delivery_jobs SET status='cancelled' WHERE announcement_id=j.announcement_id; RETURN NULL; END IF;
 IF a.publish_at>now() THEN UPDATE public.inapp_delivery_jobs SET status='pending',next_attempt_at=a.publish_at WHERE announcement_id=j.announcement_id; RETURN NULL; END IF;
 IF j.materialized_at IS NULL THEN INSERT INTO public.inapp_delivery_recipients(announcement_id,user_id) SELECT a.id,r.user_id FROM public.inapp_campaign_user_ids(j.branch_id,a.audience_filter) r ON CONFLICT DO NOTHING; END IF;
 SELECT jsonb_agg(user_id) INTO users FROM (SELECT user_id FROM public.inapp_delivery_recipients WHERE announcement_id=a.id AND status='pending' AND attempts<5 ORDER BY user_id LIMIT 20) r;
 IF users IS NULL THEN UPDATE public.inapp_delivery_jobs SET status=CASE WHEN EXISTS(SELECT 1 FROM public.inapp_delivery_recipients WHERE announcement_id=a.id AND status='failed') THEN 'failed' ELSE 'done' END,materialized_at=COALESCE(materialized_at,now()),lease_until=NULL WHERE announcement_id=a.id; UPDATE public.announcements SET dispatched_at=now() WHERE id=a.id; RETURN NULL; END IF;
 UPDATE public.inapp_delivery_jobs SET status='running',materialized_at=COALESCE(materialized_at,now()),lease_until=now()+interval '5 minutes',claim_token=token WHERE announcement_id=a.id; RETURN jsonb_build_object('announcement_id',a.id,'branch_id',j.branch_id,'title',a.title,'message',a.content,'claim_token',token,'users',users); END $$;
REVOKE ALL ON FUNCTION public.claim_inapp_delivery(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_inapp_delivery(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.finish_inapp_delivery(p_announcement_id uuid,p_claim_token uuid,p_results jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; pending boolean; BEGIN
 PERFORM 1 FROM public.inapp_delivery_jobs WHERE announcement_id=p_announcement_id AND claim_token=p_claim_token AND status='running' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Stale claim'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_results) LOOP UPDATE public.inapp_delivery_recipients SET attempts=attempts+1,status=CASE WHEN r->>'status' IN ('sent','deduped') THEN 'sent' WHEN r->>'status'='suppressed' THEN 'suppressed' WHEN attempts+1>=5 THEN 'failed' ELSE 'pending' END,last_error=CASE WHEN r->>'status' IN ('sent','deduped','suppressed') THEN NULL ELSE left(COALESCE(r->>'error','Dispatch failed'),250) END WHERE announcement_id=p_announcement_id AND user_id=(r->>'user_id')::uuid AND status='pending'; END LOOP;
 SELECT EXISTS(SELECT 1 FROM public.inapp_delivery_recipients WHERE announcement_id=p_announcement_id AND status='pending') INTO pending;
 UPDATE public.inapp_delivery_jobs SET status=CASE WHEN pending THEN 'retry' WHEN EXISTS(SELECT 1 FROM public.inapp_delivery_recipients WHERE announcement_id=p_announcement_id AND status='failed') THEN 'failed' ELSE 'done' END,lease_until=NULL,claim_token=NULL,next_attempt_at=CASE WHEN EXISTS(SELECT 1 FROM public.inapp_delivery_recipients WHERE announcement_id=p_announcement_id AND status='pending' AND attempts>0) THEN now()+interval '5 minutes' ELSE now() END WHERE announcement_id=p_announcement_id;
 UPDATE public.announcements SET dispatched_at=CASE WHEN pending THEN NULL ELSE now() END,dispatch_summary=(SELECT jsonb_build_object('sent',count(*) FILTER(WHERE status='sent'),'failed',count(*) FILTER(WHERE status='failed'),'suppressed',count(*) FILTER(WHERE status='suppressed'),'pending',count(*) FILTER(WHERE status='pending')) FROM public.inapp_delivery_recipients WHERE announcement_id=p_announcement_id) WHERE id=p_announcement_id; END $$;
REVOKE ALL ON FUNCTION public.finish_inapp_delivery(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_inapp_delivery(uuid,uuid,jsonb) TO service_role;
CREATE TRIGGER dr_block_inapp_jobs BEFORE INSERT OR UPDATE OR DELETE ON public.inapp_delivery_jobs FOR EACH ROW EXECUTE FUNCTION public.dr_block_writes(); CREATE TRIGGER dr_block_inapp_recipients BEFORE INSERT OR UPDATE OR DELETE ON public.inapp_delivery_recipients FOR EACH ROW EXECUTE FUNCTION public.dr_block_writes();